function send(from, to, amount) {
  const account = readAccount(from);
  if (account.balance < amount) throw new Error("insufficient");
  if (isFrozen(to)) throw new Error("recipient frozen");
  writeAccount(from, { ...account, balance: account.balance - amount });
  writeAccount(to, { balance: readAccount(to).balance + amount });
}
